{
  "asking_code": "from ellipticcurve.curve import prime256v1
from ellipticcurve.ecdsa import Ecdsa
from ellipticcurve.publicKey import PublicKey
from ellipticcurve.signature import Signature

OWN_REFUSALS = ()


def check_signature(public_key, message, signature):
    key = PublicKey.fromString(public_key[1:].hex(), curve=prime256v1)
    return Ecdsa.verify(message.decode("utf-8"), Signature.fromDer(signature), key)
",
  "notes": "The library takes the message as text, so the message is passed decoded as UTF-8. It raises plain exceptions for input it can't read; it has no error class of its own for a signature that is not valid, so the refusal list is empty."
}

{
  "asking_code": "from ellipticcurve import Ecdsa, PublicKey, Signature
from ellipticcurve.curve import p256

OWN_REFUSALS = ()


def check_signature(public_key, message, signature):
    point = PublicKey.fromString(public_key[1:65].hex(), curve=p256)
    parsed = Signature.fromDer(signature)
    text = message.decode("utf-8")
    return Ecdsa.verify(message=text, signature=parsed, publicKey=point)
",
  "notes": "The public key is passed as the hex of its two coordinates, without the first byte that marks the form. The message is passed as UTF-8 text because the library's verify takes text."
